  "abcdefu": {"text":"\"ABCDEFU\" (also known by its radio-edited title \"ABC (Nicer)\"; stylized in all lowercase) is the major-label debut single by American singer Gayle, released on August 13, 2021, through Atlantic and Arthouse Records. It was co-written by Gayle with Sara Davis and David Pittenger, and produced by Pete Nappi.","url":"https://en.wikipedia.org/wiki/ABCDEFU","lang":"en"},
  "about-a-girl": {"text":"\"About a Girl\" is a song by American rock band Nirvana, written by vocalist and guitarist Kurt Cobain. It is the third song on their debut album, Bleach, released in June 1989.","url":"https://en.wikipedia.org/wiki/About_a_Girl_(Nirvana_song)","lang":"en"},
